// Control::minimum_size: finite(incoming.width) and finite(incoming.height) and incoming.width >= 0 and incoming.height
// >= 0 and (maximum_size.width <= 0 or incoming.width <= maximum_size.width) and (maximum_size.height <= 0 or
// incoming.height <= maximum_size.height); else failure invalid_argument.
[[nodiscard]] constexpr bool admits_minimum_size(const Size incoming, const Size maximum_size) noexcept {
    const bool result = __builtin_isfinite(incoming.width)
                     && __builtin_isfinite(incoming.height)
                     && (incoming.width >= 0)
                     && (incoming.height >= 0)
                     && ((maximum_size.width <= 0) || (incoming.width <= maximum_size.width))
                     && ((maximum_size.height <= 0) || (incoming.height <= maximum_size.height));
    return result;
}

